import random, time

RETRYABLE = (TimeoutError, ConnectionError)

def call_with_retry(fn, deadline_s=2.0, base=0.05, cap=1.0, attempts=4):
    start = time.monotonic()
    for attempt in range(attempts):
        remaining = deadline_s - (time.monotonic() - start)
        if remaining <= 0:
            break
        try:
            return fn(timeout=remaining)
        except RETRYABLE:
            # full jitter: uniform between 0 and capped exponential delay
            sleep = random.uniform(0, min(cap, base * 2 ** attempt))
            time.sleep(min(sleep, max(0.0, remaining)))
    raise TimeoutError("deadline exceeded or retries exhausted")
